import{_ as o,l as i,o as e,c as s,v as t,p as n,x as r,d as p,i as d,S as c}from"./chunks/framework.InCnrqk-.js";const B=JSON.parse('{"title":"操作语义：进展与保持","description":"","frontmatter":{"title":"操作语义：进展与保持","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/operational-semantics.md","filePath":"cs/operational-semantics.md","lastUpdated":1789023840000}'),h={name:"cs/operational-semantics.md"};function m(_,a,u,S,E,P){const l=i("Mermaid");return e(),s("div",null,[a[1]||(a[1]=t('<h1 id="操作语义-进展与保持" tabindex="-1">操作语义：进展与保持 <a class="header-anchor" href="#操作语义-进展与保持" aria-label="Permalink to &quot;操作语义：进展与保持&quot;">​</a></h1><div class="epigraph"><p>小步：一次改写一项。大步：直接给值。上下文指出下一归约点。类型定理建立在这份关系上，而不是建立在编译器实现上。</p><footer>—— 据 Plotkin, A Structural Approach to Operational Semantics；Pierce TAPL；Wright and Felleisen, 1994 整理</footer></div><p>上一课<a href="/cs/type-soundness">类型健全性</a>已经调用了「一步」与「值」。缺口是把<strong>操作语义</strong>写清楚：小步 SOS、求值上下文、调用约定（值调用 vs 名调用）如何改变进展陈述。不重写 λ 的 β 定义，只把它收成关系 \\(t \\to t&#39;\\)。也不写指称——下一课。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>「程序做什么」若只靠编译器，无法证保持。<a href="/cs/lambda-calculus">λ 演算</a>有 β；STLC 要规定应用序还是正规序。小步：\\(\\mathrm{E}[(\\lambda x.t)\\,v] \\to \\mathrm{E}[t[v/x]]\\)。大步：\\(\\langle t,\\sigma\\rangle \\Downarrow v\\)。缺口是<strong>关系与上下文</strong>，不是 lex。</p><p>状态：引用语言要堆 \\(\\sigma\\)。进展变成：良型配置或能一步，或已是值。并发：一步是线程交错，保持更难。</p><h3 id="小步不是「解释器源码」" tabindex="-1">小步不是「解释器源码」 <a class="header-anchor" href="#小步不是「解释器源码」" aria-label="Permalink to &quot;小步不是「解释器源码」&quot;">​</a></h3><p>SOS 是数学关系。定义式解释器（Reynolds）是函数，可作可执行规范，但仍要与 SOS 对齐。本课以 SOS 为主。</p><p><span class="marginnote">Plotkin SOS。Felleisen 的求值上下文。Pierce TAPL 贯穿小步。Appel 的编译器正确性用语义对齐。本课不写 CompCert 的 Clight，那在课程末尾。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>列出语法、值、一步规则。选策略：CBN/CBV 改变哪条规则。证明：同一套进展保持。实现对照：字节码解释器应仿真小步（运行时单元）。</p>',11)),(e(),n(c,null,{default:r(()=>[d(l,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20T%5B%22%E9%A1%B9%22%5D%20--%3E%20CTX%5B%22%E6%B1%82%E5%80%BC%E4%B8%8A%E4%B8%8B%E6%96%87%22%5D%0A%20%20CTX%20--%3E%20STEP%5B%22%E5%B0%8F%E6%AD%A5%20%E2%86%92%22%5D%0A%20%20STEP%20--%3E%20V%5B%22%E5%80%BC%E6%88%96%E7%BB%A7%E7%BB%AD%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[p(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>与效应：一步可带事件标签，得带标签的转换系统，供效应类型解释。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>合流：无类型 λ 有；加状态后一般没有「同一值」的合流，只有类型保证的不卡住。不要用 Church–Rosser 当命令式语言的健全性。</p><p>大步对不终止无推导，难以谈进展；小步更适合卡住分析。大步适合证明编译器「若源停机则目标得相同值」。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写抽象机器（SECD、CEK）的全部转移。后课默认：类型定理相对 SOS。下一课指称语义：用数学对象解释项，对照操作。</p><p>也不把 CPU 流水线当操作语义。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>小步/大步是项（加状态）上的关系。</li><li>进展保持建立在小步上更自然。</li><li>策略（CBV/CBN）是规则选择。</li><li>出处：Plotkin；Felleisen；Pierce TAPL；Wright–Felleisen。</li></ul>',9))])}const f=o(h,[["render",m]]);export{B as __pageData,f as default};
